3	import java.io.File;
4	import java.util.Objects;
5	
6	import org.jetbrains.annotations.NotNull;
7	import org.jetbrains.annotations.Nullable;
8	
9	import jadx.core.dex.instructions.args.ArgType;
10	import jadx.core.dex.nodes.ClassNode;
11	import jadx.core.dex.nodes.RootNode;
12	import jadx.core.utils.StringUtils;
13	import jadx.core.utils.exceptions.JadxRuntimeException;
14	
15	public final class ClassInfo implements Comparable<ClassInfo> {
16		private final ArgType type;
17		private String name;
18		@Nullable("for inner classes")
19		private String pkg;
20		private String fullName;
21		@Nullable
22		private ClassInfo parentClass;
23		@Nullable
24		private ClassAliasInfo alias;
25	
26		private ClassInfo(RootNode root, ArgType type, boolean canBeInner) {
27			this.type = type;
28			splitAndApplyNames(root, type, canBeInner);
29		}
30	
31		public static ClassInfo fromType(RootNode root, ArgType type) {
32			ArgType clsType = checkClassType(type);
33			ClassInfo cls = root.getInfoStorage().getCls(clsType);
34			if (cls != null) {
35				return cls;
36			}
37			boolean canBeInner = root.getArgs().isMoveInnerClasses();
38			ClassInfo newClsInfo = new ClassInfo(root, clsType, canBeInner);
39			return root.getInfoStorage().putCls(newClsInfo);
40		}
41	
42		public static ClassInfo fromName(RootNode root, String clsName) {
43			return fromType(root, ArgType.object(clsName));
44		}
45	
46		public static ClassInfo fromNameWithoutCache(RootNode root, String fullClsName, boolean canBeInner) {
47			return new ClassInfo(root, ArgType.object(fullClsName), canBeInner);
48		}
49	
50		private static ArgType checkClassType(ArgType type) {
51			if (type == null) {
52				throw new JadxRuntimeException("Null class type");
53			}
54			if (type.isArray()) {
55				// TODO: check case with method declared in array class like ( clone in int[])
56				return ArgType.OBJECT;
57			}
58			if (!type.isObject() || type.isGenericType()) {
59				throw new JadxRuntimeException("Not class type: " + type);
60			}
61			if (type.isGeneric()) {
62				return ArgType.object(type.getObject());
63			}
64			return type;
65		}
66	
67		public void changeShortName(String aliasName) {
68			ClassAliasInfo newAlias;
69			String aliasPkg = getAliasPkg();
70			if (Objects.equals(name, aliasName) || StringUtils.isEmpty(aliasName)) {
71				if (Objects.equals(getPackage(), aliasPkg)) {
72					newAlias = null;
73				} else {
74					newAlias = new ClassAliasInfo(aliasPkg, name);
75				}
76			} else {
77				newAlias = new ClassAliasInfo(aliasPkg, aliasName);
78			}
79			if (newAlias != null) {
80				fillAliasFullName(newAlias);
81			}
82			this.alias = newAlias;
83		}
84	
85		public void changePkg(String aliasPkg) {
86			if (isInner()) {
87				throw new JadxRuntimeException("Can't change package for inner class: " + this);
88			}
89			if (!Objects.equals(getAliasPkg(), aliasPkg)) {
90				ClassAliasInfo newAlias = new ClassAliasInfo(aliasPkg, getAliasShortName());
91				fillAliasFullName(newAlias);
92				this.alias = newAlias;
93			}
94		}
95	
96		public void changePkgAndName(String aliasPkg, String aliasShortName) {
97			if (isInner()) {
98				throw new JadxRuntimeException("Can't change package for inner class");
99			}
100			ClassAliasInfo newAlias = new ClassAliasInfo(aliasPkg, aliasShortName);
101			fillAliasFullName(newAlias);
102			this.alias = newAlias;
103		}
104	
105		private void fillAliasFullName(ClassAliasInfo alias) {
106			if (parentClass == null) {
107				alias.setFullName(makeFullClsName(alias.getPkg(), alias.getShortName(), null, true, false));
108			}
109		}
110	
111		public String getAliasPkg() {
112			if (isInner()) {
113				return parentClass.getAliasPkg();
114			}
115			return alias == null ? getPackage() : alias.getPkg();
116		}
117	
118		public String getAliasShortName() {
119			return alias == null ? getShortName() : alias.getShortName();
120		}
121	
122		public String getAliasFullName() {
123			if (alias != null) {
124				String aliasFullName = alias.getFullName();
125				if (aliasFullName == null) {
126					return makeAliasFullName();
127				}
128				return aliasFullName;
129			}
130			if (parentClass != null && parentClass.hasAlias()) {
131				return makeAliasFullName();
132			}
133			return getFullName();
134		}
135	
136		public boolean hasAlias() {
137			if (alias != null && !alias.getShortName().equals(getShortName())) {
138				return true;
139			}
140			return parentClass != null && parentClass.hasAlias();
141		}
142	
143		public boolean hasAliasPkg() {
144			return !getPackage().equals(getAliasPkg());
145		}
146	
147		public void removeAlias() {
148			this.alias = null;
149		}
150	
151		private void splitAndApplyNames(RootNode root, ArgType type, boolean canBeInner) {
152			String fullObjectName = type.getObject();
153			String clsPkg;
154			String clsName;
155			int dot = fullObjectName.lastIndexOf('.');
156			if (dot == -1) {
157				clsPkg = "";
158				clsName = fullObjectName;
159			} else {
160				clsPkg = fullObjectName.substring(0, dot);
161				clsName = fullObjectName.substring(dot + 1);
162			}
163	
164			boolean innerCls = false;
165			if (canBeInner) {
166				int sep = clsName.lastIndexOf('$');
167				if (sep > 0 && sep != clsName.length() - 1) {
168					String parClsName = clsPkg + '.' + clsName.substring(0, sep);
169					if (clsPkg.isEmpty()) {
170						parClsName = clsName.substring(0, sep);
171					}
172					pkg = null;
173					parentClass = fromName(root, parClsName);
174					clsName = clsName.substring(sep + 1);
175					innerCls = true;
176				}
177			}
178			if (!innerCls) {
179				pkg = clsPkg;
180				parentClass = null;
181			}
182			this.name = clsName;
183			this.fullName = makeFullName();
184		}
185	
186		private static String makeFullClsName(String pkg, String shortName, ClassInfo parentClass, boolean alias, boolean raw) {
187			if (parentClass != null) {
188				String parentFullName;
189				char innerSep = raw ? '$' : '.';
190				if (alias) {
191					parentFullName = raw ? parentClass.makeAliasRawFullName() : parentClass.getAliasFullName();
192				} else {
193					parentFullName = raw ? parentClass.makeRawFullName() : parentClass.getFullName();
194				}
195				return parentFullName + innerSep + shortName;
196			}
197			return pkg.isEmpty() ? shortName : pkg + '.' + shortName;
198		}
199	
200		private String makeFullName() {
201			return makeFullClsName(pkg, name, parentClass, false, false);
202		}
203	
204		public String makeRawFullName() {
205			return makeFullClsName(pkg, name, parentClass, false, true);
206		}
207	
208		public String makeAliasFullName() {
209			return makeFullClsName(getAliasPkg(), getAliasShortName(), parentClass, true, false);
210		}
211	
212		public String makeAliasRawFullName() {
213			return makeFullClsName(getAliasPkg(), getAliasShortName(), parentClass, true, true);
214		}
215	
216		public String getAliasFullPath() {
217			String fileName = getAliasNameWithoutPackage().replace('.', '_');
218			String aliasPkg = getAliasPkg();
219			if (aliasPkg.isEmpty()) {
220				return fileName;
221			}
222			return aliasPkg.replace('.', File.separatorChar) + File.separatorChar + fileName;
223		}
224	
225		public String getFullName() {
226			return fullName;
227		}
228	
229		public String getShortName() {
230			return name;
231		}
232	
233		@NotNull
234		public String getPackage() {
235			if (parentClass != null) {
236				return parentClass.getPackage();
237			}
238			if (pkg == null) {
239				throw new JadxRuntimeException("Package is null for not inner class");
240			}
241			return pkg;
242		}
243	
244		public boolean isDefaultPackage() {
245			return getPackage().isEmpty();
246		}
247	
248		public String getRawName() {
249			return type.getObject();
250		}
251	
252		public String getAliasNameWithoutPackage() {
253			if (parentClass == null) {
254				return getAliasShortName();
255			}
256			return parentClass.getAliasNameWithoutPackage() + '.' + getAliasShortName();
257		}
258	
259		/**
260		 * Return the outer class of the class represented by this ClassInfo
261		 */
262		public @Nullable ClassInfo getParentClass() {
263			return parentClass;
264		}
265	
266		/**
267		 * Return the top outer class of the class represented by this ClassInfo
268		 */
269		public @Nullable ClassInfo getTopParentClass() {
270			if (parentClass != null) {
271				ClassInfo topCls = parentClass.getTopParentClass();
272				return topCls != null ? topCls : parentClass;
273			}
274			return null;
275		}
276	
277		public boolean isInner() {
278			return parentClass != null;
279		}
280	
281		public void notInner(RootNode root) {
282			splitAndApplyNames(root, type, false);
283			this.parentClass = null;
284		}
285	
286		public void convertToInner(ClassNode parent) {
287			splitAndApplyNames(parent.root(), type, true);
288			this.parentClass = parent.getClassInfo();
289		}
290	
291		public void updateNames(RootNode root) {
292			splitAndApplyNames(root, type, isInner());
293		}
294	
295		public ArgType getType() {
296			return type;
297		}
298	
299		@Override
300		public String toString() {
301			return getFullName();
302		}
303	
304		@Override
305		public int hashCode() {
306			return type.hashCode();
307		}
308	
309		@Override
310		public boolean equals(Object obj) {
311			if (this == obj) {
312				return true;
313			}
314			if (obj instanceof ClassInfo) {
315				return type.equals(((ClassInfo) obj).type);
316			}
317			return false;
318		}
319	
320		@Override
321		public int compareTo(@NotNull ClassInfo other) {
322			return getRawName().compareTo(other.getRawName());
323		}
324	}
