11	public final class FieldInfo implements IFieldInfoRef {
12	
13		private final ClassInfo declClass;
14		private final String name;
15		private final ArgType type;
16		private String alias;
17	
18		private FieldInfo(ClassInfo declClass, String name, ArgType type) {
19			this.declClass = declClass;
20			this.name = name;
21			this.type = type;
22			this.alias = name;
23		}
24	
25		public static FieldInfo from(RootNode root, ClassInfo declClass, String name, ArgType type) {
26			FieldInfo field = new FieldInfo(declClass, name, type);
27			return root.getInfoStorage().getField(field);
28		}
29	
30		public static FieldInfo fromRef(RootNode root, IFieldRef fieldRef) {
31			ClassInfo declClass = ClassInfo.fromName(root, fieldRef.getParentClassType());
32			FieldInfo field = new FieldInfo(declClass, fieldRef.getName(), ArgType.parse(fieldRef.getType()));
33			return root.getInfoStorage().getField(field);
34		}
35	
36		public String getName() {
37			return name;
38		}
39	
40		public ArgType getType() {
41			return type;
42		}
43	
44		public ClassInfo getDeclClass() {
45			return declClass;
46		}
47	
48		public String getAlias() {
49			return alias;
50		}
51	
52		public void setAlias(String alias) {
53			this.alias = alias;
54		}
55	
56		public void removeAlias() {
57			this.alias = name;
58		}
59	
60		public boolean hasAlias() {
61			return !Objects.equals(name, alias);
62		}
63	
64		public String getFullId() {
65			return declClass.getFullName() + '.' + name + ':' + TypeGen.signature(type);
66		}
67	
68		public String getShortId() {
69			return name + ':' + TypeGen.signature(type);
70		}
71	
72		public String getRawFullId() {
73			return declClass.makeRawFullName() + '.' + name + ':' + TypeGen.signature(type);
74		}
75	
76		public boolean equalsNameAndType(FieldInfo other) {
77			return name.equals(other.name) && type.equals(other.type);
78		}
79	
80		@Override
81		public FieldInfo getFieldInfo() {
82			return this;
83		}
84	
85		@Override
86		public boolean equals(Object o) {
87			if (this == o) {
88				return true;
89			}
90			if (o == null || getClass() != o.getClass()) {
91				return false;
92			}
93			FieldInfo fieldInfo = (FieldInfo) o;
94			return name.equals(fieldInfo.name)
95					&& type.equals(fieldInfo.type)
96					&& declClass.equals(fieldInfo.declClass);
97		}
98	
99		@Override
100		public int hashCode() {
101			int result = name.hashCode();
102			result = 31 * result + type.hashCode();
103			result = 31 * result + declClass.hashCode();
104			return result;
105		}
106	
107		@Override
108		public String toString() {
109			return declClass + "." + name + ' ' + type;
110		}
111	}
